import time
import sys
import re
import binascii

def delay_print(s, delay):
    global textSpeedMult
    for c in s:
        sys.stdout.write(c)
        sys.stdout.flush()
        yield ('sleep', textSpeedMult * delay)

def clean():
    print(chr(27) + '[2j')
    print('\x1bc')
    print('\x1bc')
    return

def lvlUp():
    global exp
    global maxHealth
    global health
    global lvl
    global attack
    global magic
    global defence
    global magDef
    global speed
    global hunger
    global maxlvl
    while exp >= lvl * 10 and lvl < maxlvl:
        clean()
        exp -= lvl * 10
        lvl += 1
        print('Level up!!! (Level {})'.format(lvl))
        maxHealth += 5 + random.randint(-2, 2)
        health = maxHealth
        attack += 2 + random.randint(-1, 1)
        magic += 2 + random.randint(-1, 1)
        defence += 2 + random.randint(-1, 1)
        magDef += 2 + random.randint(-1, 1)
        speed += 2 + random.randint(-1, 1)
        hunger = 100
        yield from learnmove()
    return
