def learnmove():
    learnAtk = 'None'
    global lvl
    global magicAbil
    if lvl == 2:
        learnAtk = 'Blow'
    if lvl == 5:
        learnAtk = 'Splash'
    if lvl == 7:
        learnAtk = 'Kindle'
    if lvl == 8:
        learnAtk = 'Stone'
    if lvl == 10:
        learnAtk = 'Shroom Fling'
    if lvl == 13:
        learnAtk = 'Icy Winds'
    if lvl == 14:
        learnAtk = 'Static'
    if lvl == 17:
        learnAtk = 'Recovery'
    if lvl == 21:
        learnAtk = 'Curse'
    if lvl == 24:
        learnAtk = 'Gust'
    if lvl == 25:
        learnAtk = 'Ocean Wave'
    if lvl == 27:
        learnAtk = 'Fireball'
    if lvl == 30:
        learnAtk = 'Rockfall'
    if lvl == 31:
        learnAtk = 'Timberrrr!!!'
    if lvl == 34:
        learnAtk = 'Ice Shot'
    if lvl == 36:
        learnAtk = 'Thunder'
    if lvl == 39:
        learnAtk = 'Great Heal'
    if lvl == 41:
        learnAtk = 'Energy Leech'
    if lvl == 45:
        learnAtk = 'Kaze-Tornado'
    if lvl == 51:
        learnAtk = 'Mizu-Tsunami'
    if lvl == 58:
        learnAtk = 'Kasai-Inferno'
    if lvl == 69:
        learnAtk = 'Tetsu-Ironslash'
    if lvl == 75:
        learnAtk = 'Shizen-Solarstrike'
    if lvl == 81:
        learnAtk = 'Kōri-Blizzard'
    if lvl == 90:
        learnAtk = 'Denkō-Stormblitz'
    if lvl == 99:
        learnAtk = 'Tendō-UltHeal'
    if lvl == 100:
        learnAtk = 'Kyūsen-Oblivion'
    if learnAtk != 'None':
        if magicAbil[0] == '-':
            magicAbil[0] = learnAtk
            yield from delay_print('You Learned {}!'.format(learnAtk), 0.075)
            yield ('sleep', 2)
        elif magicAbil[1] == '-':
            magicAbil[1] = learnAtk
            yield from delay_print('You Learned {}!'.format(learnAtk), 0.075)
            yield ('sleep', 2)
        elif magicAbil[2] == '-':
            magicAbil[2] = learnAtk
            yield from delay_print('You Learned {}!'.format(learnAtk), 0.075)
            yield ('sleep', 2)
        elif magicAbil[3] == '-':
            magicAbil[3] = learnAtk
            yield from delay_print('You Learned {}!'.format(learnAtk), 0.075)
            yield ('sleep', 2)
        else:
            nolearn = 'N'
            while nolearn.lower() != 'y' and nolearn.lower() != 'yes':
                yield from delay_print('You are trying to learn {} but your skill slots are full...\n'.format(learnAtk), 0.075)
                print('Current Moves: \n1. {}\n2. {}\n3. {}\n4. {}'.format(magicAbil[0], magicAbil[1], magicAbil[2], magicAbil[3]))
                print('Replace which slot with {}? (1-4 or 0 if not desired): '.format(learnAtk))
                forget = (yield ('input', ''))
                try:
                    forget = int(forget)
                    checkVal = True
                except ValueError:
                    checkVal = False
                forget -= 1
                if forget >= 0 and forget <= 3 and (checkVal == True):
                    magicAbil[forget] = learnAtk
                    yield from delay_print('You Learned {}!'.format(learnAtk), 0.075)
                    yield ('sleep', 2)
                    nolearn = 'Y'
                else:
                    print("Are you sure you don't want to learn {}?(Y/N): ".format(learnAtk))
                    nolearn = (yield ('input', ''))
                    yield from delay_print("You didn't learn {}.".format(learnAtk), 0.075)
                    yield ('sleep', 2)
    else:
        yield ('sleep', 1)
    return

