def updateBag(item, itemNum):
    global inventory
    global bagQuant
    try:
        inventory.index(item)
        bagCheck = True
    except ValueError:
        bagCheck = False
    if bagCheck == False:
        inventory.append(item)
        bagQuant.append(itemNum)
    else:
        bagQuant[inventory.index(item)] += itemNum
    if bagQuant[inventory.index(item)] == 0:
        inventory.remove(item)
        bagQuant.remove(0)

