def town():
    stayTown = 'Y'
    while stayTown == 'Y':
        clean()
        printTown()
        print('{:^15}{:^15}\n{:^15}{:^15}'.format('STORE', 'INN', 'DOJO', 'LEAVE'))
        yield from delay_print('Where would you like to go?: ', 0.075)
        choice = (yield ('input', ''))
        if choice.lower() == 'store' or choice.lower() == 'shop':
            yield from shop()
        elif choice.lower() == 'inn':
            yield from inn()
        elif choice.lower() == 'dojo':
            yield from dojo()
        elif choice.lower() == 'leave':
            stayTown = 'N'

def bag():
    clean()
    global bagUsed
    global bagQuant
    global health
    global worldItem
    global worldItemInfo
    global worldItemCoeff
    global worldItemType
    print('{:^15}{:^15}'.format('Item:', 'Quantity:'))
    bagUsed = 'N'
    for item in inventory:
        print('{:^15}{:^15}'.format(item, bagQuant[inventory.index(item)]))
    yield from delay_print('Enter an item to use/examine(caseSensitive): ', 0.075)
    examineItem = (yield ('input', ''))
    try:
        indexInv = inventory.index(examineItem)
        indexWorld = worldItem.index(examineItem)
        examineItem = True
    except ValueError:
        examineItem = False
    if examineItem == True:
        yield from delay_print(worldItemInfo[indexWorld], 0.075)
        yield ('sleep', 0.25)
        if worldItemType[indexWorld] == 'heal':
            yield from delay_print('\nUse item?(Y/N): ', 0.075)
            useItem = (yield ('input', ''))
            health += int(worldItemCoeff[indexWorld])
            bagQuant[indexInv] -= 1
        elif worldItemType[indexWorld] == 'weapon':
            yield from delay_print('\nEquip as Weapon?(Y/N): ', 0.075)
            useItem = (yield ('input', ''))
            if useItem.lower() == 'y' or useItem.lower() == 'yes':
                equipWeap(worldItem[indexWorld])
        elif worldItemType[indexWorld] == 'armor':
            yield from delay_print('\nEquip as Armor?(Y/N): ', 0.075)
            useItem = (yield ('input', ''))
            if useItem.lower() == 'y' or useItem.lower() == 'yes':
                equipArm(worldItem[indexWorld])
        bagUsed = 'Y'

def equipWeap(equipping):
    global weapon
    global weaponA
    global weaponS
    global weaponType
    if weapon == 0:
        weapon = equipping
        updateBag(equipping, -1)
    else:
        unequipping = weapon
        weapon = equipping
        updateBag(equipping, -1)
        updateBag(unequipping, 1)
    listTemp = worldItemCoeff[worldItem.index(equipping)]
    weaponType = worldItemElement[worldItem.index(equipping)]
    listTemp = re.split('[\\[\\]]', listTemp)
    weaponA = int(listTemp[0])
    weaponS = int(listTemp[1])

